function normalizeToken(value = "") {
  return String(value || "")
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function pickVariant(paths = [], seed = 0, fallback = "") {
  if (!paths.length) return fallback;
  const index = Math.abs(Number(seed) || 0) % paths.length;
  return paths[index] || fallback;
}

export function getHfwAssessmentImageVariant(skillId, word, level, phase, seed = 0, fallback = "") {
  const band = String(skillId || "").replace(/-/g, "_");
  const wordKey = normalizeToken(word);
  const phaseKey = `l${Number(level) >= 2 ? 2 : 1}p${Number(phase) === 2 ? 2 : 1}`;
  return pickVariant(hfwAssessmentImageVariants[band]?.[wordKey]?.[phaseKey] || [], seed, fallback);
}

export function getRhymingAssessmentImageVariant(family, targetWord, seed = 0, fallback = "") {
  const familyKey = normalizeToken(family);
  const targetKey = normalizeToken(targetWord);
  return pickVariant(rhymingAssessmentImageVariants[familyKey]?.[targetKey] || [], seed, fallback);
}
